import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const artifactPath = join(root, "artifacts", "contracts", "ChefBOT.sol", "ChefBOT.json");
const outPath = join(root, "lib", "abi", "ChefBOT.ts");

const artifact = JSON.parse(readFileSync(artifactPath, "utf8"));
if (!Array.isArray(artifact.abi)) {
  console.error("Artifact has no ABI array:", artifactPath);
  process.exit(1);
}

const banner = [
  "// AUTO-GENERATED by scripts/export-abi.mjs — do not edit by hand.",
  "// Regenerate with: npm run abi:export (after `npx hardhat build`).",
  "",
].join("\n");

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, `${banner}export const chefbotAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`);
console.log(`Wrote ${outPath} (${artifact.abi.length} ABI entries)`);
